        document.addEventListener('DOMContentLoaded', () => {


            const tabButtonsContainer = document.getElementById('tab-buttons');
            const tabButtons = document.querySelectorAll('.tab-button');
            const tabPanels = document.querySelectorAll('.tab-panel');

            tabButtonsContainer.addEventListener('click', (e) => {
                const clickedTab = e.target.closest('.tab-button');
                if (!clickedTab) return;
                const targetTab = clickedTab.dataset.tab;
                tabButtons.forEach(button => button.classList.toggle('active', button.dataset.tab === targetTab));
                tabPanels.forEach(panel => panel.classList.toggle('active', panel.id === `${targetTab}-tab`));
            });

            function populateUI(data) {
                if (!data || !data.static) {
                    console.error("Invalid data structure received.");
                    return;
                }
                const s = data.static;
                const setText = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
                const setProgress = (id, value, max = 1000) => {
                    const el = document.getElementById(id);
                    if (el) {
                        const percentage = (value / max) * 100 ;//
                        el.style.width = `${percentage}%`
                    }
                };

                const time = new Date(data.time);
                setText('time', time.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }));
                setText('weekday', s.weekday);
                setText('location', s.mc.location);
                setText('money', s.mc.money.toLocaleString('en-US'));
                setText('detection', s.situation.detection);

                setProgress('tension-gang', s.tension.gang, 100);
                setProgress('tension-official', s.tension.official, 100);
                setProgress('tension-corporate', s.tension.corporate, 100);

                if (s.opponent) { //
                    setProgress('influence-school', s.opponent.influence_school); //
                    setProgress('influence-business', s.opponent.influence_business); //
                } //

                const characters = ['mengyao', 'fangxiaoyu', 'baiqinghe', 'kemin', 'suwanzhao'];
                characters.forEach(charKey => {
                    const charData = s[charKey];
                    if (!charData) return;

                    setText(`${charKey}-friendship-value`, charData.friendship);
                    setProgress(`${charKey}-friendship-bar`, charData.friendship);
                    setText(`${charKey}-affection-value`, charData.affection);
                    setProgress(`${charKey}-affection-bar`, charData.affection);
                    setText(`${charKey}-pressure-value`, charData.pressure);
                    setProgress(`${charKey}-pressure-bar`, charData.pressure);
                    setText(`${charKey}-thoughts`, charData.thoughts);//

                    // New line to populate the virginity status
                    setText(`${charKey}-virginity`, charData.lost_virginity_to); //
                });
            }

            async function main() {
                try {
                    let data = await getVariables();
                    if (data && data.SAM_data) {
                        data = data.SAM_data;
                    }
                    populateUI(data);
                } catch (error) {
                    console.error("Failed to load or process data:", error);
                    const container = document.getElementById('notebook-container');
                    if (container) container.innerHTML = '<h2>数据加载失败</h2><p>无法获取角色信息，请检查后台连接。</p>';
                }
            }

            main();
        });
    </script>
